package org.bytefred.ktoy.core

/**
 * minicc verification fixtures, embedded as strings (commonTest has no
 * portable filesystem access).
 *
 * For each example: the C source and the GOLDEN .toys produced by pytoy's
 * minicc compile_source(src, name). ktoy's compileSourceMini(src, name)
 * must reproduce the golden output byte-for-byte. The `name` is the .toyc
 * file basename (with extension), so the "# Generated by minicc from
 * <name>" headers agree.
 *
 * Only the examples minicc ACCEPTS are embedded (probed by actually
 * compiling with pytoy minicc, exactly like examples_index). Recursive and
 * unsupported-syntax examples are left out automatically. 04-io/ examples
 * are excluded (read/write I/O, not headless-deterministic).
 *
 * Frozen fixtures: generated once from pytoy's examples/c/ and minicc (that
 * generator is gone, ktoy no longer uses pytoy). The C sources here are not
 * kept in sync with examples/; they only pin minicc's output.
 */

val MINICC_EXAMPLES: List<CExample> = listOf(
    CExample(
        name = """bit_operators.toyc""",
        cSource = """// example: bitwise operators and shifts
// description: Applies &, ^, >> and <<, which map to and, xor, right and left.
// steps: toycc 27, minicc 30
// result: 36

int main(void) {
    int x = 0xF0;              // 11110000
    int y = 0x3C;              // 00111100
    int a = x & y;             // 00110000
    int c = x ^ y;             // 11001100
    a = a >> 2;                // 00001100
    a = a << 1;                // 00011000
    return a + (c & 0x0F);     // 24 + 12
}
""",
        expectedToys = """# Generated by minicc from bit_operators.toyc
# Toy CPU assembly. 8-bit values, wrap mod 256.
# Result ends up in the accumulator at STOP.


# function main(...) — single body, marker-dispatch return
main__body: nop
        load  c_240
        store v_main__x
        load  c_60
        store v_main__y
        load  v_main__y
        store t1
        load  v_main__x
        and   t1
        store v_main__a
        load  v_main__y
        store t2
        load  v_main__x
        xor   t2
        store v_main__c
        load  v_main__a
        right
        right
        store v_main__a
        load  v_main__a
        left
        store v_main__a
        load  c_15
        store t3
        load  v_main__c
        and   t3
        store t4
        load  v_main__a
        add   t4
        stop
        stop            # end of main (halt if it falls through)

# data
v_main__x: 0
v_main__y: 0
v_main__a: 0
v_main__c: 0
t1: 0
t2: 0
t3: 0
t4: 0
c_15: 15
c_60: 60
c_240: 240
""",
